#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int M1 = 998244353;
const int M2 = 1000000007;
const int B = 1000000;
vector<int> arr[7];
int prefixSum[7];
ll limit;
ll counter, result;

void buildTree(int level, int prefix) {
    ++counter;
    arr[level].push_back((counter - prefix + M1) % M1);
    prefixSum[level] = (prefixSum[level] + (counter - prefix + M1) % M1) % M2;
    if (level == 6) return;
    for (int digit = 0; digit < 10; ++digit)
        buildTree(level + 1, prefix * 10 + digit);
}

void traverse(ll x) {
    if (x > limit) return;
    if (x * B + B - 1 <= limit && x * B * 10 > limit) {
        ll currentCount = counter;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = arr[i].size();
            int diffVal = ((currentCount - x * factor) % M1 + M1) % M1;
            int pos = lower_bound(arr[i].begin(), arr[i].end(), M1 - diffVal) - arr[i].begin();
            result = (result + 1ll * diffVal * size + prefixSum[i]) % M2;
            result = (result - 1ll * M1 * (size - pos) % M2 + M2) % M2;
            counter += size;
        }
        return;
    }
    ++counter;
    result = (result + ((counter - x) % M1 + M1) % M1) % M2;
    for (int digit = 0; digit <= 9; ++digit) traverse(x * 10 + digit);
}

int main() {
    scanf("%lld", &limit);
    buildTree(0, 0);
    for (int i = 0; i <= 6; ++i) sort(arr[i].begin(), arr[i].end());
    counter = 0;
    for (int i = 1; i <= 9; ++i) traverse(i);
    printf("%lld\n", result);
    return 0;
}
